-- Warrior RP original speech and emote catalog (enUS)
local _, addon = ...
addon.localeData.enUS.texts = {
    HEROIC_STRIKE = { name = "Heroic Strike", ziel = { "%s, consider that my polite introduction.", "*catches %s off guard with a surprisingly compact swing.*" }, gruppe = { "Know why this blade is heavy? It rarely argues back.", "*shifts weight onto the leading foot and brings the weapon down hard.*", "Some arguments don't need a second sentence.", "*drives the shoulder forward and lets the steel finish the point.*" } },
    CHARGE = { name = "Charge", ziel = { "%s, do try not to catch me!", "*storms straight toward %s, eating up the final steps.*" }, gruppe = { "If the road is blocked, I take the direct route.", "*lowers a shoulder and launches forward in a cloud of dust.*", "Coming through! That's a direction, not a warning!", "*bursts through an opening with a tremendous clatter.*" } },
    REND = { name = "Rend", ziel = { "%s, your armour has a question it can't answer.", "*finds the join between two plates on %s with a short cut.*" }, gruppe = { "Armour seams are tiny secrets. I'm curious.", "*draws the blade across an exposed gap in the guard.*", "A tailor would be horrified. I'm quite pleased.", "*draws the blade back and searches for another opening.*" } },
    HAMSTRING = { name = "Hamstring", ziel = { "%s, we're finishing this conversation right here.", "*steps past %s and sweeps a controlled blow at leg height.*" }, gruppe = { "Running away? That's a plan with serious flaws.", "*ducks low beneath the enemy's guard.*", "I dislike chasing twice. Once is plenty.", "*sweeps low with the weapon and rises into guard again.*" } },
    THUNDER_CLAP = { name = "Thunder Clap", ziel = {  }, gruppe = { "When the ground shakes, who needs a drummer?", "*stamps so hard that dust leaps from the earth.*", "Hear that? Even the earth has objections.", "*throws both arms wide as a dull boom rolls through the line.*" } },
    CLEAVE = { name = "Cleave", ziel = {  }, gruppe = { "If you stand shoulder to shoulder, you can share the trouble.", "*sends the weapon sweeping across a crowded arc.*", "I hope you left enough room. I didn't.", "*pivots on one heel and carries the momentum into the next arc.*" } },
    EXECUTE = { name = "Execute", ziel = { "%s, the discussion ends here.", "*fixes %s with one calm breath, then lets the blade fall.*" }, gruppe = { "I gave you every chance to withdraw.", "*waits for a heartbeat, then brings down a final-looking blow.*", "Negotiations are over.", "*tightens the grip and closes the last opening.*" } },
    SUNDER_ARMOR = { name = "Sunder Armor", ziel = { "%s, your smith will have questions.", "*tests a seam in %s's armour with a sharp strike.*" }, gruppe = { "Lovely breastplate. Shame about the rivets.", "*sets the blade against a loose edge of armour.*", "Expensive steel isn't the same as good protection.", "*traces a hard line along a gap between metal plates.*" } },
    SHIELD_BLOCK = { name = "Shield Block", ziel = {  }, gruppe = { "You'll have to knock first. This door stays closed.", "*turns the shield's rim to catch an incoming strike.*", "A good shield listens before it answers.", "*plants both boots and refuses to give an inch.*" } },
    SHIELD_BASH = { name = "Shield Bash", ziel = { "%s, save the next syllable.", "*tries to interrupt %s with a sharp shove of the shield.*" }, gruppe = { "Hush. Let's see if I can interrupt your spell.", "*drives the shield forward between two syllables.*", "My answer to magic comes with a wooden handle.", "*steps close and snaps the shield out without warning.*" } },
    TAUNT = { name = "Taunt", ziel = { "%s, look at me, not the vulnerable!", "*plants the feet before %s and taps the shield invitingly.*" }, gruppe = { "Over here! The trouble has my name on it.", "*rattles the sword hilt against the shield three times.*", "The others are busy. I'm not.", "*steps out from the line and beckons the enemies closer.*" } },
    BATTLE_SHOUT = { name = "Battle Shout", ziel = {  }, gruppe = { "Heads up, ranks closed! No one falls alone today!", "*beats the weapon hilt against the shield in rhythm.*", "You've legs to stand on and hearts to endure. Use both!", "*rises before the allies and lifts the blade high.*" } },
    DEMORALIZING_SHOUT = { name = "Demoralizing Shout", ziel = {  }, gruppe = { "The first of you are shaking. The rest will notice soon!", "*unleashes a rough, deep cry from the chest.*", "Look around. Who are you still fighting for?", "*points the blade at the wavering enemy line.*" } },
    REVENGE = { name = "Revenge", ziel = { "%s, your own momentum is working for me now.", "*catches %s's attack and answers without hesitation.*" }, gruppe = { "Thanks for the opportunity. It's coming right back.", "*turns a weapon aside and strikes into the opening.*", "I forget faces. Never blows.", "*rolls straight from defence into a counterattack.*" } },
    OVERPOWER = { name = "Overpower", ziel = { "%s, I accept your invitation.", "*moves barely a hand's breadth from %s and thrusts forward.*" }, gruppe = { "There's a gap. How generous of you.", "*slips past the missed strike and takes the open angle.*", "Miss me once, invite me in.", "*turns an enemy misstep into a swift counter.*" } },
    MORTAL_STRIKE = { name = "Mortal Strike", ziel = { "%s, this is the moment you overlooked.", "*sends the heavy weapon hurtling toward %s.*" }, gruppe = { "I'm not saving anything for a second try.", "*sets both hands on the weapon and throws the body behind one strike.*", "Some duels end with words. Not this one.", "*steps forward and guides the steel with merciless precision.*" } },
    WHIRLWIND = { name = "Whirlwind", ziel = {  }, gruppe = { "Go on, stand in a circle. Makes things easier.", "*spins through the press of bodies with the weapon extended.*", "I like sharing. Today it's steel.", "*sends the blade singing around in a wide sweep.*" } },
    BLOODTHIRST = { name = "Bloodthirst", ziel = { "%s, this is about to get uncomfortable.", "*closes on %s quickly without abandoning the guard.*" }, gruppe = { "The pulse is racing. The hand stays steady.", "*draws a sharp breath and presses the attack without mercy.*", "Anger doesn't mean I'm inaccurate.", "*surges forward with wild eyes and a measured grip.*" } },
    INTERCEPT = { name = "Intercept", ziel = { "%s, shortcuts are my specialty.", "*sprints across %s's path before they can escape.*" }, gruppe = { "A head start is borrowed time.", "*bursts from the melee and cuts off the escape.*", "You're running? Excellent. I needed the exercise.", "*springs off the ground and lands across the fleeing path.*" } },
    PUMMEL = { name = "Pummel", ziel = { "%s, the next word stays yours.", "*steps into %s's movement and breaks its rhythm.*" }, gruppe = { "Too many words. Not enough guard.", "*disrupts the casting motion with a sharp, precise strike.*", "Were you saying something? No? Good.", "*knocks an arm out of rhythm with a compact blow.*" } },
    SWEEPING_STRIKES = { name = "Sweeping Strikes", ziel = {  }, gruppe = { "Why do half the job when there's a whole battle?", "*carries one swing smoothly into a second arc.*", "More enemies? Fewer trips.", "*keeps the blade moving through the crush instead of withdrawing it.*" } },
    DEATH_WISH = { name = "Death Wish", ziel = {  }, gruppe = { "Reason made its case. I disagreed.", "*loosens the grip for a moment, then commits to the attack.*", "I know the risk. Not sure they do.", "*glances once at the lowered guard before lunging forward.*" } },
    RECKLESSNESS = { name = "Recklessness", ziel = {  }, gruppe = { "Caution was yesterday. Today we act.", "*casts hesitation aside without loosening the weapon grip.*", "You can lecture me tomorrow. If we have one.", "*throws the whole body into a furious chain of strikes.*" } },
    LAST_STAND = { name = "Last Stand", ziel = {  }, gruppe = { "This far. Not one step further.", "*hauls upright once more and lifts the shield.*", "Still standing. That should answer you.", "*sets shaking legs into the breach again.*" } },
    SHIELD_WALL = { name = "Shield Wall", ziel = {  }, gruppe = { "Behind me! No private heroics!", "*locks the shield close and braces into the allied line.*", "Anyone going through me will need patience.", "*closes the final gap between shield and armour.*" } },
    RETALIATION = { name = "Retaliation", ziel = {  }, gruppe = { "If you strike, you should enjoy the echo.", "*leaves a narrow gap in the guard and answers each attack with steel.*", "Come on then. I have a moment for each of you.", "*plants the feet and waits for the first impatient blows.*" } },
    MOCKING_BLOW = { name = "Mocking Blow", ziel = { "%s, do show me what you can do!", "*feigns a careless guard before %s and laughs.*" }, gruppe = { "Are you dangerous or merely loud?", "*lets the weapon point hang too low and invites the foe closer.*", "Sorry. Mistook you for a training dummy.", "*makes a cheeky swing and grins over the shield.*" } },
    BERSERKER_RAGE = { name = "Berserker Rage", ziel = {  }, gruppe = { "Fear? It has no room in my head today.", "*rolls the shoulders as if shaking off an invisible weight.*", "Fear can wait outside. Fury's coming in.", "*blows out a hard breath and holds an unbroken stare.*" } },
    BLOODRAGE = { name = "Bloodrage", ziel = {  }, gruppe = { "Pain is a message. I'll answer later.", "*strikes a fist against the chest and gathers fighting spirit.*", "My heart's still beating. That's enough explanation.", "*grits the teeth and tightens the shoulders beneath the armour.*" } },
    DISARM = { name = "Disarm", ziel = { "%s, your hands are safer without steel.", "*tries to turn %s's weapon arm with a precise lever.*" }, gruppe = { "Beautiful sword. May I see it a moment?", "*tries to turn the enemy blade free with a short twist.*", "Let's see if you're as talkative without a weapon.", "*tries to catch the weapon's grip and twist it out of line.*" } },
    INTIMIDATING_SHOUT = { name = "Intimidating Shout", ziel = {  }, gruppe = { "Run while you still remember the way!", "*throws a savage roar over the heads of the enemy.*", "That was the friendly warning. The next comes with steel.", "*crashes the hilt against the shield and bares the teeth.*" } },
    CHALLENGING_SHOUT = { name = "Challenging Shout", ziel = {  }, gruppe = { "ALL OF YOU, TO ME! I've room for every grudge!", "*throws both arms wide and challenges the entire enemy line.*", "Leave the others! I'm your problem today!", "*hammers the shield and bellows at the approaching foes.*" } },
    SLAM = { name = "Slam", ziel = { "%s, hold tightly to whatever you still own.", "*brings a heavy, deliberate overhead strike toward %s.*" }, gruppe = { "It's not a hammer. Won't feel much different, though.", "*raises the weapon overhead and drops it with full weight.*", "One clean hit beats five half-hearted ones.", "*pauses for a heartbeat and lets the weapon crash down.*" } },
    DEVASTATE = { name = "Devastate", ziel = { "%s, you're running out of protection.", "*hits the weakened armour join on %s once more.*" }, gruppe = { "Already loose? Let's finish the job.", "*strikes an already weakened patch of armour.*", "Looks like your smith saved money in the wrong place.", "*taps the exposed seam, then strikes again.*" } },
    SHIELD_SLAM = { name = "Shield Slam", ziel = { "%s, don't watch only my sword.", "*drives the shield toward %s at the perfect moment.*" }, gruppe = { "Shields can close doors. Usually at face level.", "*rips the shield from its guard and thrusts the rim forward.*", "Whoever said defence was polite?", "*lunges one step and lets the shield do the talking.*" } },
    CONCUSSION_BLOW = { name = "Concussion Blow", ziel = { "%s, let me borrow your sense of urgency.", "*tries to land a short, staggering blow on %s.*" }, gruppe = { "I'll try to throw you off your stride.", "*tries to land a heavy blow in the gap between two movements.*", "I'll try to give everyone a moment of silence.", "*shortens the grip and swings with startling force.*" } },
    VICTORY_RUSH = { name = "Victory Rush", ziel = { "%s, I've only just begun.", "*turns toward %s after a brief, triumphant breath.*" }, gruppe = { "One down. The others are still standing.", "*uses the sudden breath of victory to surge forward.*", "We can celebrate later. Something's still moving.", "*taps the chest once and presses on.*" } },
    BATTLE_STANCE = { name = "Battle Stance", ziel = {  }, gruppe = { "Two feet of good sense separate courage from stupidity.", "*plants both feet shoulder-width apart and rolls the blade loosely.*", "I'll stay ready. The rest can make up its mind.", "*balances the weight between shield arm and sword hand.*" } },
    DEFENSIVE_STANCE = { name = "Defensive Stance", ziel = {  }, gruppe = { "If they want my friends, they must convince my shield.", "*widens the stance and lifts the shield before the allies.*", "The loudest roar won't win this one.", "*drops the centre of gravity and becomes a wall behind the guard.*" } },
    BERSERKER_STANCE = { name = "Berserker Stance", ziel = {  }, gruppe = { "Whoever said anger makes you blind has never looked properly.", "*draws deep breath and assumes a fierce, forward stance.*", "The world has become very simple: forward.", "*loosens the shoulders, lowers the weapon, then snaps it up.*" } },
    PIERCING_HOWL = { name = "Piercing Howl", ziel = {  }, gruppe = { "If you hear me, you're already too close.", "*lets loose a howl that cuts through the surrounding clamour.*", "No, that wasn't a pack of wolves. Just me.", "*throws the head back and sustains a long, harsh cry.*" } },
    SPEARING_STRIKE = { name = "Spearing Strike", ziel = { "%s, there's room between your plates.", "*sets the weapon point into a gap in %s's guard.*" }, gruppe = { "The opening is narrow. My point isn't.", "*steps directly forward with the weapon extended.*", "Armour is strong. Angles are stronger.", "*turns the wrist toward a weak spot and drives the point home.*" } },
    TACTICAL_MASTERY = { name = "Tactical Mastery", ziel = {  }, gruppe = { "The difference between courage and foolishness is good footwork.", "*shifts position barely an inch and keeps the battlefield in view.*", "A battlefield isn't a dice game. You learn to read it.", "*studies every path, foe and retreat without lowering the weapon.*" } },
}
